// The GitHub API returns raw JSON content
const packageJson = $input.first().json;
// Pass the raw content as a string for the actor
return [{ json: { packageJsonContent: JSON.stringify(packageJson) } }];

const raw = $input.first().json;
const results = Array.isArray(raw) ? raw : [raw];

const critical = results.filter(r => r.severity === 'critical');
const high = results.filter(r => r.severity === 'high');
const medium = results.filter(r => r.severity === 'medium');
const suspicious = results.filter(r => r.isSuspicious === true);

return [{
  json: {
    critical,
    high,
    medium,
    suspicious,
    criticalCount: critical.length,
    highCount: high.length,
    mediumCount: medium.length,
    suspiciousCount: suspicious.length,
    hasCritical: critical.length > 0,
    hasHighOrCritical: critical.length > 0 || high.length > 0,
    totalIssues: critical.length + high.length + medium.length + suspicious.length
  }
}];

const data = $input.first().json;

const formatVuln = (v) => `• *${v.packageName}@${v.installedVersion}* — ${v.cveId || 'Advisory'} (CVSS: ${v.cvssScore || 'N/A'})
  Fix: ${v.fixedInVersion ? 'Update to ' + v.fixedInVersion : 'No patch available'}
  ${v.cveUrl ? `<${v.cveUrl}|View CVE>` : ''}`;

const criticalSection = data.critical.length > 0
  ? `
🚨 *CRITICAL (${data.criticalCount})*
${data.critical.map(formatVuln).join('
')}` : '';

const highSection = data.high.length > 0
  ? `
⚠️ *HIGH (${data.highCount})*
${data.high.map(formatVuln).join('
')}` : '';

const suspiciousSection = data.suspicious.length > 0
  ? `
🔍 *SUSPICIOUS PATTERNS (${data.suspiciousCount})* — Investigate before deploying
${data.suspicious.map(s => `• ${s.packageName} — ${s.suspiciousReason || 'Unusual activity detected'}`).join('
')}` : '';

const message = `🔒 *CVE Monitor Alert — Action Required*

*Repository:* YOUR_GITHUB_ORG/YOUR_REPO
*Date:* ${new Date().toLocaleDateString('en-GB')}

${criticalSection}${highSection}${suspiciousSection}

_Do not deploy until these vulnerabilities are addressed._`;

return [{ json: { message } }];
